// Lesson: A2A: Agent-to-Agent Protocol (phase 13 / lesson 19)
// Go port of code/main.py. Go standard library only.
// Source: phases/13-tools-and-protocols/19-a2a-protocol/docs/en.md
// Run: go run code/main.go

package main

import (
	"bytes"
	"crypto/rand"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"net"
	"net/http"
	"strconv"
	"strings"
	"sync"
)

const a2aVersion = "1.0"

type agentInterface struct {
	URL             string `json:"url"`
	ProtocolBinding string `json:"protocolBinding"`
	ProtocolVersion string `json:"protocolVersion"`
}

type agentSkill struct {
	ID          string   `json:"id"`
	Name        string   `json:"name"`
	Description string   `json:"description"`
	Tags        []string `json:"tags"`
	InputModes  []string `json:"inputModes"`
	OutputModes []string `json:"outputModes"`
}

type agentCard struct {
	Name                string           `json:"name"`
	Description         string           `json:"description"`
	Version             string           `json:"version"`
	SupportedInterfaces []agentInterface `json:"supportedInterfaces"`
	Capabilities        map[string]bool  `json:"capabilities"`
	DefaultInputModes   []string         `json:"defaultInputModes"`
	DefaultOutputModes  []string         `json:"defaultOutputModes"`
	Skills              []agentSkill     `json:"skills"`
}

var writerAgentCard = agentCard{
	Name:        "writer-agent",
	Description: "Drafts technical summaries and reports from source material.",
	Version:     "1.0.0",
	SupportedInterfaces: []agentInterface{
		{URL: "https://writer.example.com/a2a", ProtocolBinding: "JSONRPC", ProtocolVersion: a2aVersion},
	},
	Capabilities:       map[string]bool{"streaming": true, "pushNotifications": false},
	DefaultInputModes:  []string{"text/plain"},
	DefaultOutputModes: []string{"text/markdown"},
	Skills: []agentSkill{
		{
			ID:          "draft_report",
			Name:        "Draft report",
			Description: "Given source material and a target length, produce a report.",
			Tags:        []string{"writing", "summarization"},
			InputModes:  []string{"text/plain", "application/pdf", "application/json"},
			OutputModes: []string{"text/markdown"},
		},
	},
}

type part struct {
	Text      *string        `json:"text,omitempty"`
	Raw       *string        `json:"raw,omitempty"`
	URL       *string        `json:"url,omitempty"`
	Data      map[string]any `json:"data,omitempty"`
	Filename  string         `json:"filename,omitempty"`
	MediaType string         `json:"mediaType,omitempty"`
}

func partContent(p part) string {
	var present []string
	if p.Text != nil {
		present = append(present, "text")
	}
	if p.Raw != nil {
		present = append(present, "raw")
	}
	if p.URL != nil {
		present = append(present, "url")
	}
	if p.Data != nil {
		present = append(present, "data")
	}
	if len(present) != 1 {
		panic(fmt.Sprintf("a Part holds exactly one of text, raw, url, data; got %v", present))
	}
	return present[0]
}

type message struct {
	MessageID string `json:"messageId"`
	Role      string `json:"role"`
	Parts     []part `json:"parts"`
	TaskID    string `json:"taskId,omitempty"`
}

type taskStatus struct {
	State   string   `json:"state"`
	Message *message `json:"message,omitempty"`
}

type artifact struct {
	ArtifactID string `json:"artifactId"`
	Name       string `json:"name"`
	Parts      []part `json:"parts"`
}

type task struct {
	ID        string     `json:"id"`
	ContextID string     `json:"contextId"`
	Status    taskStatus `json:"status"`
	Artifacts []artifact `json:"artifacts"`
	History   []message  `json:"history"`
}

type rpcError struct {
	Code    int    `json:"code"`
	Message string `json:"message"`
}

type rpcRequest struct {
	JSONRPC string `json:"jsonrpc"`
	ID      int    `json:"id"`
	Method  string `json:"method"`
	Params  struct {
		Message message `json:"message"`
	} `json:"params"`
}

type sendResult struct {
	Task task `json:"task"`
}

type rpcResponse struct {
	JSONRPC string      `json:"jsonrpc"`
	ID      int         `json:"id"`
	Result  *sendResult `json:"result,omitempty"`
	Error   *rpcError   `json:"error,omitempty"`
}

func str(s string) *string { return &s }

func uuid4() string {
	b := make([]byte, 16)
	if _, err := rand.Read(b); err != nil {
		panic(err)
	}
	b[6] = b[6]&0x0f | 0x40
	b[8] = b[8]&0x3f | 0x80
	h := hex.EncodeToString(b)
	return h[0:8] + "-" + h[8:12] + "-" + h[12:16] + "-" + h[16:20] + "-" + h[20:]
}

func newMessage(role string, parts []part, taskID string) message {
	return message{MessageID: uuid4(), Role: role, Parts: parts, TaskID: taskID}
}

type writer struct {
	mu    sync.Mutex
	store map[string]*task
}

func transition(t *task, state string, msg *message) {
	fmt.Printf("    WRITER  : %s -> %s\n", t.Status.State, state)
	t.Status = taskStatus{State: state}
	if msg != nil {
		t.Status.Message = msg
		t.History = append(t.History, *msg)
	}
}

func pyStr(v any) string {
	switch x := v.(type) {
	case string:
		return x
	case nil:
		return "None"
	case bool:
		if x {
			return "True"
		}
		return "False"
	case float64:
		if x == float64(int64(x)) {
			return strconv.FormatInt(int64(x), 10)
		}
		return strconv.FormatFloat(x, 'g', -1, 64)
	}
	data, _ := json.Marshal(v)
	return string(data)
}

func finish(t *task, length string) {
	text := fmt.Sprintf("[writer agent] %s summary of provided source: "+
		"topic identified, key points extracted, conclusion drafted.", length)
	t.Artifacts = append(t.Artifacts, artifact{
		ArtifactID: uuid4(),
		Name:       "summary",
		Parts:      []part{{Text: str(text), MediaType: "text/markdown"}},
	})
	transition(t, "TASK_STATE_COMPLETED", nil)
}

func (w *writer) hasTask(id string) bool {
	if id == "" {
		return true
	}
	w.mu.Lock()
	defer w.mu.Unlock()
	_, ok := w.store[id]
	return ok
}

func (w *writer) sendMessage(msg message) task {
	w.mu.Lock()
	defer w.mu.Unlock()
	var t *task
	if msg.TaskID != "" {
		t = w.store[msg.TaskID]
	} else {
		t = &task{
			ID:        "task_" + strings.ReplaceAll(uuid4(), "-", "")[:10],
			ContextID: uuid4(),
			Status:    taskStatus{State: "TASK_STATE_SUBMITTED"},
			Artifacts: []artifact{},
			History:   []message{},
		}
		w.store[t.ID] = t
		fmt.Printf("    WRITER  : created task %s\n", t.ID)
	}
	t.History = append(t.History, msg)
	transition(t, "TASK_STATE_WORKING", nil)
	var dataPayloads []map[string]any
	for _, p := range msg.Parts {
		if partContent(p) == "data" {
			dataPayloads = append(dataPayloads, p.Data)
		}
	}
	var length any
	ok := false
	if len(dataPayloads) > 0 {
		length, ok = dataPayloads[0]["targetLength"]
	}
	if !ok {
		ask := newMessage("ROLE_AGENT", []part{{Text: str("Please specify targetLength as a data part.")}}, t.ID)
		transition(t, "TASK_STATE_INPUT_REQUIRED", &ask)
	} else {
		finish(t, pyStr(length))
	}
	return *t
}

func (w *writer) ServeHTTP(rw http.ResponseWriter, r *http.Request) {
	var req rpcRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(rw, err.Error(), http.StatusBadRequest)
		return
	}
	resp := rpcResponse{JSONRPC: "2.0", ID: req.ID}
	switch {
	case r.Header.Get("A2A-Version") != a2aVersion:
		resp.Error = &rpcError{Code: -32009, Message: "Version not supported"}
	case req.Method != "SendMessage":
		resp.Error = &rpcError{Code: -32601, Message: "Method not found"}
	case !w.hasTask(req.Params.Message.TaskID):
		resp.Error = &rpcError{Code: -32001, Message: "Task not found"}
	default:
		resp.Result = &sendResult{Task: w.sendMessage(req.Params.Message)}
	}
	rw.Header().Set("Content-Type", "application/json")
	if err := json.NewEncoder(rw).Encode(resp); err != nil {
		panic(err)
	}
}

func sendMessage(endpoint string, requestID int, msg message) task {
	req := rpcRequest{JSONRPC: "2.0", ID: requestID, Method: "SendMessage"}
	req.Params.Message = msg
	body, err := json.Marshal(req)
	if err != nil {
		panic(err)
	}
	fmt.Printf("  research : %s (A2A-Version: %s)\n", req.Method, a2aVersion)
	httpReq, err := http.NewRequest(http.MethodPost, endpoint, bytes.NewReader(body))
	if err != nil {
		panic(err)
	}
	httpReq.Header.Set("Content-Type", "application/json")
	httpReq.Header.Set("A2A-Version", a2aVersion)
	httpResp, err := http.DefaultClient.Do(httpReq)
	if err != nil {
		panic(err)
	}
	defer httpResp.Body.Close()
	var resp rpcResponse
	if err := json.NewDecoder(httpResp.Body).Decode(&resp); err != nil {
		panic(err)
	}
	if resp.Error != nil {
		panic(fmt.Sprintf("rpc error %d: %s", resp.Error.Code, resp.Error.Message))
	}
	return resp.Result.Task
}

func researchAgentFlow(endpoint string) {
	bar := strings.Repeat("=", 72)
	fmt.Println(bar)
	fmt.Println("PHASE 13 LESSON 18 - A2A CALL FROM RESEARCH TO WRITER")
	fmt.Println(bar)

	fmt.Println("\n--- research agent fetches writer Agent Card ---")
	view := struct {
		Name                string           `json:"name"`
		SupportedInterfaces []agentInterface `json:"supportedInterfaces"`
		Skills              []agentSkill     `json:"skills"`
	}{writerAgentCard.Name, writerAgentCard.SupportedInterfaces, writerAgentCard.Skills}
	out, err := json.MarshalIndent(view, "", "  ")
	if err != nil {
		panic(err)
	}
	fmt.Println(string(out))

	skillID := writerAgentCard.Skills[0].ID
	fmt.Printf("\n  research agent will invoke skill: %s\n", skillID)

	msg := newMessage("ROLE_USER", []part{
		{Text: str("Summarize the attached paper.")},
		{Raw: str(base64.StdEncoding.EncodeToString([]byte("fake-pdf"))), Filename: "paper.pdf", MediaType: "application/pdf"},
	}, "")
	t := sendMessage(endpoint, 1, msg)
	fmt.Printf("  research : task state = %s\n", t.Status.State)

	if t.Status.State == "TASK_STATE_INPUT_REQUIRED" {
		fmt.Println("\n--- research agent supplies the missing data ---")
		followup := newMessage("ROLE_USER", []part{
			{Data: map[string]any{"targetLength": "3 paragraphs"}, MediaType: "application/json"},
		}, t.ID)
		t = sendMessage(endpoint, 2, followup)
		fmt.Printf("  research : task state = %s\n", t.Status.State)
	}

	fmt.Println("\n--- research agent reads artifact ---")
	if len(t.Artifacts) > 0 {
		a := t.Artifacts[0]
		fmt.Printf("  name      : %s\n", a.Name)
		fmt.Printf("  mediaType : %s\n", a.Parts[0].MediaType)
		fmt.Printf("  content   : %s\n", *a.Parts[0].Text)
	}

	fmt.Println("\n--- lifecycle observation ---")
	fmt.Printf("  final state : %s\n", t.Status.State)
	fmt.Printf("  history     : %d\n", len(t.History))
}

func main() {
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		panic(err)
	}
	srv := &http.Server{Handler: &writer{store: map[string]*task{}}}
	go func() {
		if err := srv.Serve(ln); err != nil && err != http.ErrServerClosed {
			panic(err)
		}
	}()
	researchAgentFlow("http://" + ln.Addr().String() + "/a2a")
	if err := srv.Close(); err != nil {
		panic(err)
	}
}

"""Phase 13 Lesson 19 - A2A agent-to-agent protocol.

Research agent calls writer agent via A2A 1.0:
  1. Research agent fetches writer's Agent Card
  2. Sends SendMessage with text + file parts
  3. Writer task moves TASK_STATE_WORKING -> TASK_STATE_INPUT_REQUIRED
     -> TASK_STATE_WORKING -> TASK_STATE_COMPLETED
  4. Research agent receives an Artifact

Stdlib only; in-process transport stands in for JSON-RPC over HTTP.
Wire names follow A2A 1.0.1: docs/specification.md and specification/a2a.proto.

Run: python code/main.py
"""

from __future__ import annotations

import base64
import json
import uuid


A2A_VERSION = "1.0"

WRITER_AGENT_CARD = {
    "name": "writer-agent",
    "description": "Drafts technical summaries and reports from source material.",
    "version": "1.0.0",
    "supportedInterfaces": [
        {
            "url": "https://writer.example.com/a2a",
            "protocolBinding": "JSONRPC",
            "protocolVersion": A2A_VERSION,
        }
    ],
    "capabilities": {"streaming": True, "pushNotifications": False},
    "defaultInputModes": ["text/plain"],
    "defaultOutputModes": ["text/markdown"],
    "skills": [
        {
            "id": "draft_report",
            "name": "Draft report",
            "description": "Given source material and a target length, produce a report.",
            "tags": ["writing", "summarization"],
            "inputModes": ["text/plain", "application/pdf", "application/json"],
            "outputModes": ["text/markdown"],
        }
    ],
}

PART_CONTENT_FIELDS = ("text", "raw", "url", "data")


def part_content(part: dict) -> str:
    present = [name for name in PART_CONTENT_FIELDS if name in part]
    if len(present) != 1:
        raise ValueError(f"a Part holds exactly one of text, raw, url, data; got {present}")
    return present[0]


def new_message(role: str, parts: list[dict], task_id: str | None = None) -> dict:
    message = {"messageId": str(uuid.uuid4()), "role": role, "parts": parts}
    if task_id:
        message["taskId"] = task_id
    return message


TASK_STORE: dict[str, dict] = {}


def transition(task: dict, state: str, message: dict | None = None) -> None:
    print(f"    WRITER  : {task['status']['state']} -> {state}")
    task["status"] = {"state": state}
    if message:
        task["status"]["message"] = message
        task["history"].append(message)


def writer_send_message(params: dict) -> dict:
    message = params["message"]
    task_id = message.get("taskId")
    if task_id:
        task = TASK_STORE[task_id]
    else:
        task = {
            "id": f"task_{uuid.uuid4().hex[:10]}",
            "contextId": str(uuid.uuid4()),
            "status": {"state": "TASK_STATE_SUBMITTED"},
            "artifacts": [],
            "history": [],
        }
        TASK_STORE[task["id"]] = task
        print(f"    WRITER  : created task {task['id']}")
    task["history"].append(message)
    transition(task, "TASK_STATE_WORKING")
    data_payloads = [p["data"] for p in message["parts"] if part_content(p) == "data"]
    if not data_payloads or "targetLength" not in data_payloads[0]:
        transition(task, "TASK_STATE_INPUT_REQUIRED", new_message("ROLE_AGENT", [
            {"text": "Please specify targetLength as a data part."}
        ], task["id"]))
    else:
        finish(task, data_payloads[0]["targetLength"])
    return {"task": task}


def finish(task: dict, length: str) -> None:
    text = f"[writer agent] {length} summary of provided source: "\
           f"topic identified, key points extracted, conclusion drafted."
    task["artifacts"].append({
        "artifactId": str(uuid.uuid4()),
        "name": "summary",
        "parts": [{"text": text, "mediaType": "text/markdown"}],
    })
    transition(task, "TASK_STATE_COMPLETED")


def writer_endpoint(headers: dict, request: dict) -> dict:
    response = {"jsonrpc": "2.0", "id": request["id"]}
    if headers.get("A2A-Version") != A2A_VERSION:
        response["error"] = {"code": -32009, "message": "Version not supported"}
    elif request["method"] != "SendMessage":
        response["error"] = {"code": -32601, "message": "Method not found"}
    elif request["params"]["message"].get("taskId") and \
            request["params"]["message"]["taskId"] not in TASK_STORE:
        response["error"] = {"code": -32001, "message": "Task not found"}
    else:
        response["result"] = writer_send_message(request["params"])
    return response


def send_message(request_id: int, message: dict) -> dict:
    request = {"jsonrpc": "2.0", "id": request_id, "method": "SendMessage",
               "params": {"message": message}}
    print(f"  research : {request['method']} (A2A-Version: {A2A_VERSION})")
    response = writer_endpoint({"A2A-Version": A2A_VERSION}, request)
    return response["result"]["task"]


def research_agent_flow() -> None:
    print("=" * 72)
    print("PHASE 13 LESSON 18 - A2A CALL FROM RESEARCH TO WRITER")
    print("=" * 72)

    print("\n--- research agent fetches writer Agent Card ---")
    print(json.dumps({k: WRITER_AGENT_CARD[k] for k in ("name", "supportedInterfaces", "skills")},
                     indent=2))

    skill = WRITER_AGENT_CARD["skills"][0]
    skill_id = skill["id"]
    print(f"\n  research agent will invoke skill: {skill_id}")

    msg = new_message("ROLE_USER", [
        {"text": "Summarize the attached paper."},
        {"raw": base64.b64encode(b"fake-pdf").decode(), "filename": "paper.pdf",
         "mediaType": "application/pdf"},
    ])
    task = send_message(1, msg)
    print(f"  research : task state = {task['status']['state']}")

    if task["status"]["state"] == "TASK_STATE_INPUT_REQUIRED":
        print("\n--- research agent supplies the missing data ---")
        followup = new_message("ROLE_USER", [
            {"data": {"targetLength": "3 paragraphs"}, "mediaType": "application/json"},
        ], task["id"])
        task = send_message(2, followup)
        print(f"  research : task state = {task['status']['state']}")

    print("\n--- research agent reads artifact ---")
    if task["artifacts"]:
        artifact = task["artifacts"][0]
        print(f"  name      : {artifact['name']}")
        print(f"  mediaType : {artifact['parts'][0]['mediaType']}")
        print(f"  content   : {artifact['parts'][0]['text']}")

    print("\n--- lifecycle observation ---")
    print(f"  final state : {task['status']['state']}")
    print(f"  history     : {len(task['history'])}")


if __name__ == "__main__":
    research_agent_flow()

// Phase 13 Lesson 19: A2A agent-to-agent protocol, in TypeScript.
//
// Research agent calls writer agent via A2A 1.0:
//   1. Research agent fetches writer's Agent Card
//   2. Sends SendMessage with text + file parts
//   3. Writer task moves TASK_STATE_WORKING -> TASK_STATE_INPUT_REQUIRED
//      -> TASK_STATE_WORKING -> TASK_STATE_COMPLETED
//   4. Research agent receives an Artifact
//
// Stdlib only; in-process transport stands in for JSON-RPC over HTTP.
//
// Spec references:
//   A2A protocol         https://a2a-protocol.org/latest/specification/
//   Agent Card schema    https://a2a-protocol.org/latest/specification/#8-agent-discovery-the-agent-card
//
// Run: npx tsx code/main.ts

import { randomUUID } from "node:crypto";

const A2A_VERSION = "1.0";

type AgentInterface = { url: string; protocolBinding: string; protocolVersion: string };

type Capabilities = { streaming: boolean; pushNotifications: boolean };

type Skill = {
  id: string;
  name: string;
  description: string;
  tags: string[];
  inputModes: string[];
  outputModes: string[];
};

type AgentCard = {
  name: string;
  description: string;
  version: string;
  supportedInterfaces: AgentInterface[];
  capabilities: Capabilities;
  defaultInputModes: string[];
  defaultOutputModes: string[];
  skills: Skill[];
};

const WRITER_AGENT_CARD: AgentCard = {
  name: "writer-agent",
  description: "Drafts technical summaries and reports from source material.",
  version: "1.0.0",
  supportedInterfaces: [
    {
      url: "https://writer.example.com/a2a",
      protocolBinding: "JSONRPC",
      protocolVersion: A2A_VERSION,
    },
  ],
  capabilities: { streaming: true, pushNotifications: false },
  defaultInputModes: ["text/plain"],
  defaultOutputModes: ["text/markdown"],
  skills: [
    {
      id: "draft_report",
      name: "Draft report",
      description: "Given source material and a target length, produce a report.",
      tags: ["writing", "summarization"],
      inputModes: ["text/plain", "application/pdf", "application/json"],
      outputModes: ["text/markdown"],
    },
  ],
};

type PartMeta = { filename?: string; mediaType?: string };
type TextPart = PartMeta & { text: string };
type RawPart = PartMeta & { raw: string };
type UrlPart = PartMeta & { url: string };
type DataPart = PartMeta & { data: Record<string, unknown> };
type Part = TextPart | RawPart | UrlPart | DataPart;

const PART_CONTENT_FIELDS = ["text", "raw", "url", "data"] as const;

function partContent(part: Part): (typeof PART_CONTENT_FIELDS)[number] {
  const present = PART_CONTENT_FIELDS.filter((name) => name in part);
  if (present.length !== 1) {
    throw new Error(`a Part holds exactly one of text, raw, url, data; got ${present}`);
  }
  return present[0];
}

type Role = "ROLE_USER" | "ROLE_AGENT";

type Message = { messageId: string; role: Role; parts: Part[]; taskId?: string };

type Artifact = { artifactId: string; name: string; parts: Part[] };

type TaskState =
  | "TASK_STATE_SUBMITTED"
  | "TASK_STATE_WORKING"
  | "TASK_STATE_INPUT_REQUIRED"
  | "TASK_STATE_COMPLETED"
  | "TASK_STATE_FAILED"
  | "TASK_STATE_CANCELED";

type Task = {
  id: string;
  contextId: string;
  status: { state: TaskState; message?: Message };
  artifacts: Artifact[];
  history: Message[];
};

type JsonRpcRequest = {
  jsonrpc: "2.0";
  id: number;
  method: string;
  params: { message: Message };
};

type JsonRpcResponse = {
  jsonrpc: "2.0";
  id: number;
  result?: { task: Task };
  error?: { code: number; message: string };
};

const TASK_STORE = new Map<string, Task>();

function newMessage(role: Role, parts: Part[], taskId?: string): Message {
  const message: Message = { messageId: randomUUID(), role, parts };
  if (taskId) message.taskId = taskId;
  return message;
}

function transition(task: Task, state: TaskState, message?: Message): void {
  console.log(`    WRITER  : ${task.status.state} -> ${state}`);
  task.status = { state };
  if (message) {
    task.status.message = message;
    task.history.push(message);
  }
}

function finish(task: Task, length: string): void {
  const text =
    `[writer agent] ${length} summary of provided source: ` +
    `topic identified, key points extracted, conclusion drafted.`;
  task.artifacts.push({
    artifactId: randomUUID(),
    name: "summary",
    parts: [{ text, mediaType: "text/markdown" }],
  });
  transition(task, "TASK_STATE_COMPLETED");
}

function writerSendMessage(params: { message: Message }): { task: Task } {
  const { message } = params;
  let task: Task;
  if (message.taskId) {
    const existing = TASK_STORE.get(message.taskId);
    if (!existing) throw new Error(`unknown task ${message.taskId}`);
    task = existing;
  } else {
    const id = `task_${randomUUID().replace(/-/g, "").slice(0, 10)}`;
    task = {
      id,
      contextId: randomUUID(),
      status: { state: "TASK_STATE_SUBMITTED" },
      artifacts: [],
      history: [],
    };
    TASK_STORE.set(id, task);
    console.log(`    WRITER  : created task ${id}`);
  }
  task.history.push(message);
  transition(task, "TASK_STATE_WORKING");

  const data = message.parts.find((p): p is DataPart => partContent(p) === "data");
  if (!data || !("targetLength" in data.data)) {
    transition(
      task,
      "TASK_STATE_INPUT_REQUIRED",
      newMessage("ROLE_AGENT", [{ text: "Please specify targetLength as a data part." }], task.id),
    );
  } else {
    finish(task, String(data.data.targetLength));
  }
  return { task };
}

function writerEndpoint(headers: Record<string, string>, request: JsonRpcRequest): JsonRpcResponse {
  const response: JsonRpcResponse = { jsonrpc: "2.0", id: request.id };
  if (headers["A2A-Version"] !== A2A_VERSION) {
    response.error = { code: -32009, message: "Version not supported" };
  } else if (request.method !== "SendMessage") {
    response.error = { code: -32601, message: "Method not found" };
  } else if (request.params.message.taskId && !TASK_STORE.has(request.params.message.taskId)) {
    response.error = { code: -32001, message: "Task not found" };
  } else {
    response.result = writerSendMessage(request.params);
  }
  return response;
}

function sendMessage(requestId: number, message: Message): Task {
  const request: JsonRpcRequest = {
    jsonrpc: "2.0",
    id: requestId,
    method: "SendMessage",
    params: { message },
  };
  console.log(`  research : ${request.method} (A2A-Version: ${A2A_VERSION})`);
  const response = writerEndpoint({ "A2A-Version": A2A_VERSION }, request);
  if (!response.result) throw new Error(`A2A error ${response.error?.code}`);
  return response.result.task;
}

